ALTER TABLE "Inventory" ADD CONSTRAINT inventory_nonnegative CHECK ("onHand">=0 AND reserved>=0 AND reserved<="onHand" AND "lowThreshold">=0);
ALTER TABLE "InventoryReservation" ADD CONSTRAINT reservation_positive CHECK(quantity>0), ADD CONSTRAINT reservation_state CHECK(state IN ('ACTIVE','CONSUMED','RELEASED'));
ALTER TABLE "Order" ADD CONSTRAINT order_money CHECK(subtotal>=0 AND discount>=0 AND discount<=subtotal AND "shippingFee">=0 AND "shippingDiscount">=0 AND "shippingDiscount"<="shippingFee" AND tax>=0 AND total=subtotal-discount+"shippingFee"-"shippingDiscount"+tax), ADD CONSTRAINT order_method CHECK(method IN ('QR','COD'));
ALTER TABLE "OrderItem" ADD CONSTRAINT item_money CHECK(price>0 AND cost>=0 AND quantity BETWEEN 1 AND 20 AND discount>=0 AND discount<=price*quantity);
ALTER TABLE "Product" ADD CONSTRAINT product_money CHECK(price>0 AND cost>=0 AND ("originalPrice" IS NULL OR "originalPrice">=price));
ALTER TABLE "ProductVariant" ADD CONSTRAINT variant_money CHECK(price IS NULL OR price>0);
ALTER TABLE "CartItem" ADD CONSTRAINT cart_quantity CHECK(quantity BETWEEN 1 AND 20);
ALTER TABLE "Payment" ADD CONSTRAINT payment_money CHECK(amount>0 AND received>=0 AND refunded>=0 AND refunded<=received AND "providerCode" BETWEEN 1 AND 9007199254740991);
ALTER TABLE "PaymentTransaction" ADD CONSTRAINT transaction_money CHECK(amount>0 AND currency='VND');
ALTER TABLE "Coupon" ADD CONSTRAINT coupon_limits CHECK(used>=0 AND used<="maxUses" AND "maxUses">0 AND "perUserLimit">0 AND "minSubtotal">=0 AND "maxDiscount">=0 AND value>0 AND type IN ('PERCENT','FIXED') AND (type!='PERCENT' OR value<=100) AND "endsAt">"startsAt");
ALTER TABLE "CouponRedemption" ADD CONSTRAINT redemption_positive CHECK(amount>0);
ALTER TABLE "Review" ADD CONSTRAINT review_rating CHECK(rating BETWEEN 1 AND 5);
ALTER TABLE "ReturnItem" ADD CONSTRAINT return_quantity CHECK(quantity>0),ADD CONSTRAINT inspection_state CHECK(inspection IN ('PENDING','PASS','FAIL'));
ALTER TABLE "Refund" ADD CONSTRAINT refund_money CHECK(amount>0), ADD CONSTRAINT refund_state CHECK(status IN ('REQUESTED','APPROVED','COMPLETED','REJECTED'));
ALTER TABLE "Shipment" ADD CONSTRAINT cod_limits CHECK(fee>=0 AND "codExpected">=0 AND "codCollected">=0 AND "codCollected"<="codExpected" AND "codRemitted">=0 AND "codRemitted"<="codCollected");
ALTER TABLE "CODSettlement" ADD CONSTRAINT settlement_money CHECK(amount>0 AND fee>=0 AND fee<=amount);
ALTER TABLE "Address" ADD CONSTRAINT address_location CHECK((lat IS NULL AND lng IS NULL) OR (lat BETWEEN -90 AND 90 AND lng BETWEEN -180 AND 180)), ADD CONSTRAINT address_confirmed CHECK(confirmed=true);
ALTER TABLE "User" ADD CONSTRAINT email_normalized CHECK(email=lower(btrim(email)));
CREATE UNIQUE INDEX address_one_default ON "Address"("userId") WHERE "isDefault"=true;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX product_search_trgm ON "Product" USING GIN("searchText" gin_trgm_ops);
ALTER SEQUENCE "Payment_providerCode_seq" RESTART WITH 100000;
